import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'
import { clsx } from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { formatTanggalV3 } from '@/helper/date'
import { RekonsiliasiObatTransfer } from '@/models/rekonsiliasi-obat-transfer'
import { getRekonsiliasiObatTransfer } from '@/services/daftar-obat-harian'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { RekonsiliasiObatPulangTable } from './rekonsiliasi-obat-pulang-table'

// import { Edit } from 'lucide-react'

interface ReportRekonsiliasiObatTransferProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportRekonsiliasiObatTransfer({
  isReport = false,
  noreg = '',
  no = '',
}: ReportRekonsiliasiObatTransferProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rekonsiliasiObatTransfer, noreg],
    queryFn: () => getRekonsiliasiObatTransfer({ noreg: noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const Selected = ({ data }: { data: RekonsiliasiObatTransfer }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-2'>
            REKONSILIASI OBAT SAAT PASIEN TRANSFER ANTAR UNIT
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}
        </div>

        <div className='p-2'>
          <RekonsiliasiObatPulangTable data={data.obat} />
        </div>

        <div className='flex p-2 items-start justify-around mt-[100px]'>
          <div className='flex flex-col gap-4 items-center text-center text-xs'>
            {data.apoteker != null && data.apoteker.ttd == '' ? (
              <>
                <p className='text-sm'>Apoteker</p>
                <QRCode
                  value={data.apoteker.nama ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({data.apoteker.nama ?? '-'})</p>
              </>
            ) : (
              <>
                <p className='text-sm'>Apoteker</p>

                <img
                  alt='ttd'
                  src={`${import.meta.env.VITE_BASE_API_URL}/app/images/rekonsiliasi/${data.apoteker.ttd}`}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({data.apoteker.nama ?? '-'})</p>
              </>
            )}
          </div>{' '}
          <div className='flex flex-col gap-4 items-center text-center text-xs'>
            {data.apoteker != null && data.perawat_menyerahkan.ttd == '' ? (
              <>
                <p className='text-sm'>Perawat Menyerahkan</p>
                <QRCode
                  value={data.perawat_menyerahkan.nama ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({data.perawat_menyerahkan.nama ?? '-'})</p>
              </>
            ) : (
              <>
                <p className='text-sm'>Perawat Menyerahkan</p>

                <img
                  alt='ttd'
                  src={`${import.meta.env.VITE_BASE_API_URL}/app/images/rekonsiliasi/${data.perawat_menyerahkan.ttd}`}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({data.perawat_menyerahkan.nama ?? '-'})</p>
              </>
            )}
          </div>
          <div className='flex flex-col gap-4 items-center text-center text-xs'>
            {data.apoteker != null && data.perawat_menerima.ttd == '' ? (
              <>
                <p className='text-sm'>Perawat Menerima</p>
                <QRCode
                  value={data.perawat_menerima.nama ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({data.perawat_menerima.nama ?? '-'})</p>
              </>
            ) : (
              <>
                <p className='text-sm'>Perawat Menerima</p>

                <img
                  alt='ttd'
                  src={`${import.meta.env.VITE_BASE_API_URL}/app/images/rekonsiliasi/${data.perawat_menerima.ttd}`}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({data.perawat_menerima.nama ?? '-'})</p>
              </>
            )}
          </div>
        </div>

        {/* Content */}
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {item.bagian}
          </Button>
        ))}

      {result.length > 0 ? <Selected data={result[index]} /> : null}
    </>
  )
}
