export default function RekamMedis() {
  // store
  const { pasien } = usePasienStore((state) => state)
  const { dialogId, setDialogId } = useGlobalStore((state) => state)

  // state
  const [showSideBar, setShowSideBar] = useState(true)
  const [selectedMenu, setSelectedMenu] = useState<string>('')
  const [selectedNo, setSelectedNo] = useState<string>('')

  const [selectedNoreg, setSelectedNoreg] = useState<string>('')
  // const [kdBagian, setKdBagian] = useState<string>('')
  const [menuSearch, setMenuSearch] = useState<string>('')

  // query

  const {
    data: pasienRegister,
    isLoading,
    isError,
  } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.listRegisterPasien, pasien?.no_rm],
    queryFn: () => getRegisterPasien({ no_rm: pasien!.no_rm }),
  })

  useEffect(() => {
    if (pasienRegister != null && pasienRegister.response.length > 0) {
      setSelectedNoreg(pasienRegister.response[0].noreg)
    }
  }, [pasienRegister])

  const refetch = (noreg: string) => {
    const kb = pasienRegister?.response.find(
      (item) => item.noreg == noreg
    )?.kd_bagian

    setSelectedNoreg(noreg)
    // setKdBagian(kb ?? '')
    console.log('noreg', noreg)
    console.log('kb', kb)
  }

  // to report path
  const to = selectedMenu.replace(/[/\s]+/g, '-').toLowerCase()

  // filter menu berdasarkan pencarian
  const filteredMenu = LIST_MENU.filter((item) => {
    const q = menuSearch.trim().toLowerCase()
    if (q == '') return true
    return (
      item.nama.toLowerCase().includes(q) || item.no.toLowerCase().includes(q)
    )
  })

  // render komponen report sesuai menu yang dipilih
  const renderReport = (menu: string) => {
    switch (menu) {
      case 'Identitas Pasien':
        return (
          <ReportIdentitasPasien
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'General Consent Rawat Jalan':
        return (
          <RekamMedisGeneralConsent
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Persetujuan Umum (General Consent)':
        return (
          <RekamMedisGeneralConsentRanap
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Triase':
        return <Triase isReport noreg={selectedNoreg} no={selectedNo} />
      case 'Asesmen Awal Kebidanan Ponek':
        return (
          <AsesmenAwalMedisPonek
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Transfer Pasien':
        return <ReportTransferPasien isReport noreg={selectedNoreg} />
      case 'Asesmen Awal Medis':
        return (
          <AsesmenAwalMedis isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Asesmen Awal Dewasa Rawat Jalan':
        return (
          <ReportAsesmenAwalDewasaRajal
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Reasesmen Risiko Jatuh Dewasa':
        return <ReportResikoJatuhMorse isReport noreg={selectedNoreg} />
      case 'Reasesmen Risiko Jatuh Anak':
        return <ReportResikoJatuh isReport noreg={selectedNoreg} />
      case 'Catatan Terintegrasi (CPPT)':
        return <CPPTResume isReport noreg={selectedNoreg} no={selectedNo} />
      case 'Lembaran Konsul':
        return <LembaranKonsul isReport noreg={selectedNoreg} no={selectedNo} />
      case 'Rekonsiliasi Obat':
        return <ReportRekonsiliasiObatMasuk isReport noreg={selectedNoreg} />
      case 'Daftar Obat Harian (timbal balik)':
        return <DaftarObatHarian noreg={selectedNoreg} />
      case 'Rekonsiliasi Obat Transfer Antar Unit':
        return <ReportRekonsiliasiObatTransfer isReport noreg={selectedNoreg} />
      case 'Rekonsiliasi Obat Saat Dibawa Pulang':
        return <ReportRekonsiliasiObatPulang isReport noreg={selectedNoreg} />
      case 'Resume Medis (timbal balik)':
        return (
          <ReportResumeRanap isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Ringkasan Pasien Pulang':
        return (
          <ReportResumeRanap isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Ringkasan Masuk dan Keluar':
        return (
          <ReportRingkasanMasuk
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Pulang Atas Permintaan Pasien':
        return (
          <ReportPernyataanPulang
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
            no_rm={pasien?.no_rm}
          />
        )
      case 'Pengkajian Restrain':
        return <ReportRestrain isReport noreg={selectedNoreg} no={selectedNo} />
      case 'MPP':
        return (
          <ReportFormulirManager
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Pemberian Informasi':
        return (
          <ReportPemberianInformasi
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Form Persetujuan Tindakan Kedokteran':
        return (
          <ReportPersetujuanTindakanKedokteran
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Form Pengantar Rawat Inap':
        return (
          <FormPengantarRawatInap
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Persetujuan/Penolakan Tindakan Transfusi Darah':
        return (
          <ReportTindakanTransfusiDarah
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Persetujuan Pemeriksaan Test HIV':
        return (
          <ReportPersetujuanHiv
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
            no_rm={pasien?.no_rm}
          />
        )

      case 'Double Check':
        return (
          <ReportDoubleCheck isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Hasil Pemeriksaan Penunjang':
        return <HasilPemeriksaan isReport noreg={selectedNoreg} />
      case 'Formulir Handover':
        return <CPPTSbarResume isReport noreg={selectedNoreg} no={selectedNo} />
      case 'Laporan Operasi':
        return <OperationReport isReport noreg={selectedNoreg} />
      case 'Renpra':
        return (
          <PelaksanaanKeperawatan
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
            no_rm={pasien?.no_rm}
          />
        )
      case 'Catatan Perkembangan Pasien (termasuk kebidanan)':
        return <CPPT isReport no_rm={pasien?.no_rm} />
      case 'Catatan Edukasi Terintegrasi':
        return (
          <ReportEdukasiTerintegrasi
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
            no_rm={pasien?.no_rm}
          />
        )
      case 'Rencana Asuhan Keperawatan':
        return (
          <ReportAsuhanKeperawatan
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      case 'Asuhan Keperawatan Hemodialisa':
        return (
          <ReportAsesmenKeperawatanHD
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
            no_rm={pasien?.no_rm}
          />
        )
      case 'Laporan Skrining Gizi':
        return (
          <ReportSkriningGizi isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Formulir Asuhan Gizi':
        return (
          <ReportAsuhanGizi isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Asesmen Keperawatan Bayi Baru Lahir':
        return <AsesmenKeperawatanBayi />
      case 'Asesmen Awal Keperawatan Dewasa':
        return (
          <ReportPengkajianKeperawatanDewasa
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
            no_rm={pasien?.no_rm}
          />
        )
      case 'Asesmen Awal Keperawatan Anak':
        return <AsesmenKeperawatanAnak />
      case 'Analisa Data':
        return (
          <ReportAnalisaData isReport noreg={selectedNoreg} no={selectedNo} />
        )
      case 'Cairan Intake Output':
        return (
          <ReportMonitoringCairan
            isReport
            noreg={selectedNoreg}
            no={selectedNo}
          />
        )
      default:
        return <ReportBelumTersedia nama={menu} no={selectedNo} />
    }
  }

  if (isLoading) return <Loading className='text-white' />
  if (isError) return <Error className='text-red-[500]' />

  return (
    <>
      {/* Dialog Detail Pasien  */}
      <Dialog
        modal
        open={dialogId == 'dialog-rekam-medis'}
        onOpenChange={() => {
          setDialogId('')
          setSelectedNoreg('')
        }}
      >
        <DialogTitle></DialogTitle>
        <DialogDescription></DialogDescription>
        <DialogContent className='min-h-screen max-w-screen-2xl'>
          <div className='flex'>
            {/* Left Content */}
            {showSideBar && (
              <div className='w-[250px] border p-4'>
                {/* Profile Pasien */}
                <div className='h-[200px] border flex flex-col justify-center items-center text-center mb-4'>
                  <Avatar className='h-[100px] w-[100px]'>
                    <AvatarImage
                      src={
                        pasien?.jenis_kelamin == 'Laki-Laki'
                          ? images.man
                          : images.woman
                      }
                      alt='pasien photos'
                    />
                    <AvatarFallback className='text-2xl'>
                      {/* {pasien?.nama_pasien} */}
                    </AvatarFallback>
                  </Avatar>
                  <h3 className='py-2'>{pasien?.nama_pasien}</h3>
                  <h3 className='text-xs'>{pasien?.noreg}</h3>
                  <h3 className='text-xs'>{pasien?.no_rm}</h3>
                </div>
                {/* Profile Pasien */}
                <div className='px-1 w-full'>
                  <Input
                    type='text'
                    value={menuSearch}
                    onChange={(e) => setMenuSearch(e.target.value)}
                    placeholder='Cari menu...'
                    className='h-9 text-xs'
                  />
                  <div className='overflow-y-scroll mb-2 rounded-md mt-4 p-1 w-full h-[calc(100vh-300px)]'>
                    {filteredMenu.length > 0 ? (
                      filteredMenu.map((item: Menu, index: number) => (
                        <p
                          className='text-xs border border-gray-300 rounded-md p-2 mb-1 hover:bg-primaryColor hover:text-white hover:cursor-pointer'
                          onClick={() => {
                            setSelectedMenu(item.nama)
                            setSelectedNo(item.no)
                          }}
                        >
                          {index + 1}. {item.no} - {item.nama}
                        </p>
                      ))
                    ) : (
                      <p className='text-xs text-gray-400 text-center p-2'>
                        Menu tidak ditemukan
                      </p>
                    )}
                  </div>
                </div>
              </div>
            )}
            {/* Left Content */}
            {/* Right Content */}
            <div className='w-full'>
              {/* AppBar */}
              <div className='h-[50px] px-2 w-full bg-primaryColor flex items-center justify-between'>
                <div className='flex items-center gap-2'>
                  <Sidebar
                    className='text-white hover:cursor-pointer'
                    onClick={() => setShowSideBar((prev) => !prev)}
                  />
                  <h3 className='text-lg font-medium text-white'>
                    {selectedMenu}
                  </h3>
                </div>
                {/* Print */}
                <Link
                  disabled={selectedNoreg == ''}
                  to={`/report/${to}-rekam-medis`}
                  search={{
                    noreg: selectedNoreg,
                    no: selectedNo,
                    no_rm: pasien?.no_rm,
                  }}
                  target='_blank'
                >
                  <Printer className='text-white mr-10 hover:cursor-pointer' />
                </Link>{' '}
                {/* Print */}
              </div>
              {/* AppBar */}
              <div className='w-full border h-[calc(100vh-32px)] overflow-y-scroll p-4'>
                {/* Select No Reg */}
                <div className='flex items-center gap-2'>
                  <div />
                  <Select onValueChange={refetch} value={selectedNoreg}>
                    <SelectTrigger className='w-full'>
                      <SelectValue placeholder='Pilih data kunjungan' />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        {pasienRegister != null &&
                          pasienRegister.response.map((item, index) => (
                            <SelectItem key={index} value={item.noreg}>
                              {item.tanggal} - {item.noreg} - {item.pelayanan} -{' '}
                              {item.bagian}
                            </SelectItem>
                          ))}
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                </div>
                {/* Select No Reg */}

                {/* Report */}
                <div className='p-2 mt-4'>
                  {renderReport(selectedMenu)}
                  {/* Report */}
                </div>
              </div>
            </div>
            {/* Right Content */}
          </div>
        </DialogContent>
      </Dialog>
      {/* Dialog Detail Pasien  */}
    </>
  )
}
