import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { cn } from '@/lib/utils'
import { SkorGizi } from '@/models/skrining-gizi'
import { getSkriningGizi } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportSkriningGiziProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

function SkorRow({ no, listSkor }: { no: number; listSkor?: SkorGizi[] }) {
  const list = listSkor ?? []
  const hasil = list.find((s) => s.is_active)?.skor

  return (
    <div className='flex'>
      <SimpleColumn
        name={`${no}`}
        className='w-[30px] p-1'
        className2='text-[9px]'
      />
      <SimpleColumn
        isChild={
          <div className='w-full'>
            {list.map((s, i) => (
              <p
                key={i}
                className={cn(
                  'text-[9px] border-b border-black last:border-0 px-1',
                  s.is_active && 'bg-green-200'
                )}
              >
                {s.deskripsi}
              </p>
            ))}
          </div>
        }
        className='p-0 flex-1'
      />
      <SimpleColumn
        isChild={
          <div className='w-full'>
            {list.map((s, i) => (
              <p
                key={i}
                className={cn(
                  'text-[9px] text-center border-b border-black last:border-0',
                  s.is_active && 'bg-green-200'
                )}
              >
                {s.skor}
              </p>
            ))}
          </div>
        }
        className='p-0 flex-1'
      />
      <SimpleColumn
        isLast
        isChild={
          <p className='text-[14px] font-bold'>{hasil != null ? hasil : '-'}</p>
        }
        className='p-1 flex-1'
      />
    </div>
  )
}

export function ReportSkriningGizi({
  isReport = false,
  no = 'RM.',
  noreg = '',
}: ReportSkriningGiziProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.skriningGizi, noreg],
    queryFn: () => getSkriningGizi(noreg),
    enabled: noreg != '',
  })

  const list = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR SKRINING GIZI
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {list.length === 0 ? (
          <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
        ) : (
          <div className='mb-2'>
            {list.map((item, idx) => (
              <div key={idx} className='mb-6'>
                <p className='text-[10px] mb-2'>
                  Tanggal : {formatTanggalV3(item.tanggal) ?? item.tanggal} -
                  Jam : {item.jam}
                </p>

                {/* Tabel Diagnosa */}
                <div className='mb-2'>
                  <div className='flex'>
                    <SimpleColumn
                      head
                      name='NO.'
                      className='w-[30px] p-1'
                      className2='text-[9px]'
                    />
                    <SimpleColumn
                      head
                      name='KODE'
                      className='p-1 flex-1'
                      className2='text-[9px]'
                    />
                    <SimpleColumn
                      head
                      name='Deskripsi'
                      className='p-1 flex-1'
                      className2='text-[9px]'
                    />
                    <SimpleColumn
                      head
                      name='Diagnosa'
                      isLast
                      className='p-1 flex-1'
                      className2='text-[9px]'
                    />
                  </div>
                  {item.diagnosa?.map((d, i) => (
                    <div key={i} className='flex'>
                      <SimpleColumn
                        name={`${i + 1}`}
                        className='w-[30px] p-1'
                        className2='text-[9px]'
                      />
                      <SimpleColumn
                        name={d.diagnosa}
                        className='p-1 flex-1'
                        className2='text-[9px]'
                      />
                      <SimpleColumn
                        name={d.description}
                        className='p-1 flex-1'
                        className2='text-[9px] text-left'
                      />
                      <SimpleColumn
                        isLast
                        name={d.type?.toUpperCase()}
                        className='p-1 flex-1'
                        className2='text-[9px]'
                      />
                    </div>
                  ))}
                </div>

                {/* Box skrining fisik */}
                <div className='border border-black mb-2'>
                  <div className='flex border-b border-black'>
                    <div className='flex-1 p-1 text-[9px]'>
                      BB :{' '}
                      <span className='font-semibold'>{item.skrining?.bb}</span>{' '}
                      Kg
                    </div>
                    <div className='flex-1 p-1 text-[9px] border-l border-black'>
                      TB :{' '}
                      <span className='font-semibold'>{item.skrining?.tb}</span>{' '}
                      Cm
                    </div>
                    <div className='flex-1 p-1 text-[9px] border-l border-black'>
                      IMT :{' '}
                      <span className='font-semibold'>
                        {item.skrining?.imt}
                      </span>{' '}
                      Kg/m2
                    </div>
                  </div>
                  <div className='flex'>
                    <div className='flex-1 p-1 text-[9px]'>
                      ULNA :{' '}
                      <span className='font-semibold'>
                        {item.skrining?.ulna}
                      </span>{' '}
                      Cm
                    </div>
                    <div className='flex-1 p-1 text-[9px] border-l border-black'>
                      LLA :{' '}
                      <span className='font-semibold'>
                        {item.skrining?.lla}
                      </span>{' '}
                      Cm
                    </div>
                    <div className='flex-1 p-1 text-[9px] border-l border-black'>
                      BBI :{' '}
                      <span className='font-semibold'>
                        {item.skrining?.bbi}
                      </span>{' '}
                      Kg
                    </div>
                  </div>
                </div>

                {/* Tabel Skor */}
                <div className='mb-2'>
                  <div className='flex'>
                    <SimpleColumn
                      head
                      name='NO.'
                      className='w-[30px] p-1'
                      className2='text-[9px]'
                    />
                    <SimpleColumn
                      head
                      name='KATEGORI'
                      className='p-1 flex-1'
                      className2='text-[9px]'
                    />
                    <SimpleColumn
                      head
                      name='SKOR'
                      className='p-1 flex-1'
                      className2='text-[9px]'
                    />
                    <SimpleColumn
                      head
                      name='HASIL'
                      isLast
                      className='p-1 flex-1'
                      className2='text-[9px]'
                    />
                  </div>
                  <SkorRow no={1} listSkor={item.skor_imt} />
                  <SkorRow no={2} listSkor={item.skor_bb} />
                  <SkorRow no={3} listSkor={item.skor_penyakit_akut} />
                </div>

                {/* JUMLAH KESELURUHAN */}
                <div className='flex border border-black mb-2'>
                  <div className='flex-1 p-2 text-[10px] font-semibold'>
                    JUMLAH KESELURUHAN.
                  </div>
                  <div className='w-[80px] border-l border-black flex items-center justify-center text-[16px] font-bold'>
                    {item.total_skor}
                  </div>
                </div>

                {/* Tanda tangan Ahli Gizi */}
                <div className='flex flex-col items-center gap-1 p-3 text-center text-xs'>
                  <p className='font-semibold'>TANDA TANGAN</p>
                  <QRCode
                    value={item.nama_ahli_gizi ?? '-'}
                    className='h-[70px] w-[70px]'
                  />
                  <p>( {item.nama_ahli_gizi ?? ''} )</p>
                  <p className='font-semibold'>AHLI GIZI</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
