import { SimpleColumn } from '@/components/simple-column'
import { RiwayatAlergiObat } from '@/models/rekonsiliasi-obat-pulang-masuk'

export function RiwayatObatAlergiTable({
  data,
}: {
  data: RiwayatAlergiObat[]
}) {
  if (data.length > 0) {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1'
            className2='text-[10px]'
          />
          <SimpleColumn
            head
            name='Nama Obat Yang Menimbulkan Alergi'
            className='p-1 flex-1'
            className2='text-[10px]'
          />
          <SimpleColumn
            head
            name='Derajat Alergi'
            className='p-1 flex-1'
            className2='text-[10px]'
          />
          <SimpleColumn
            head
            name='Reaksi Alergi'
            className='p-1 flex-1'
            className2='text-[10px]'
            isLast
          />
        </div>
        {data != null &&
          data.length > 0 &&
          data.map((item, i) => (
            <div className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[50px] p-1 border-t-0'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.nama_obat}
                className='w-[50px] p-1 border-t-0 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.derajat_alergi}
                className='w-[50px] p-1 border-t-0 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.reaksi_alergi}
                className='w-[50px] p-1 border-t-0 flex-1'
                className2='text-[10px]'
                isLast
              />
            </div>
          ))}
      </div>
    )
  } else {
    return (
      <p className='text-[10px] text-center font-medium'>
        Tidak ada obat yang menimbulkan alergi
      </p>
    )
  }
}
