import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { getIdentitasPasien } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

// import { Edit } from 'lucide-react'

interface ReportIdentitasPasienProps {
  isReport?: boolean
  noreg?: string
  no?: string
  no_rm?: string
}

export function ReportIdentitasPasien({
  isReport = false,
  no = '',
  no_rm = '',
}: ReportIdentitasPasienProps) {
  const { pasien } = usePasienStore((state) => state)

  const noRm = no_rm || pasien?.no_rm || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.identitasPasien, noRm],
    queryFn: () => getIdentitasPasien(noRm),
    enabled: noRm != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result?.no_rm == '')
    return <EmptyPlaceholder message='Data tidak ditemukan' />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          IDENTITAS PASIEN
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}
        {/* Informasi Pasien */}

        <div className='p-2 border border-black'>
          <TextField
            title='Nama Lengkap Pasien'
            value={result?.nama_pasien}
            boxed
          />
          <TextField title='Tempat Lahir' value={result?.tempat_lahir} boxed />
          <TextField title='Tanggal Lahir' value={result?.tgl_lahir} boxed />
          <TextField title='Nomor NIK - KTP' value={result?.nik} boxed />
          <TextField title='Status' value={result?.status} boxed />
          <TextField
            title='Jenis Kelamin'
            value={result?.jenis_kelamin}
            boxed
          />
          <TextField title='Pendidikan' value={result?.pendidikan} boxed />
          <TextField title='Agama' value={result?.agama} boxed />
          <TextField title='Pekerjaan' value={result?.pekerjaan} boxed />
          <TextField title='Suku' value={result?.suku} boxed />
          <TextField title='Alamat' value={result?.alamat} boxed />
          <TextField title='Kelurahan' value={result?.kelurahan} boxed />
          <TextField title='Kecamatan' value={result?.kecamatan} boxed />
          <TextField
            title='Kabupaten / Kotamadya'
            value={result?.kabupaten}
            boxed
          />
          <TextField title='Propinsi' value={result?.propinsi} boxed />
          <TextField title='Nomor Telepon / HP' value={result?.no_hp} boxed />
          <TextField
            title='Nomor Ayah/Ibu/Suami'
            value={result?.cp_number}
            boxed
          />
          <TextField title='Istri/Saudara' value='' boxed />
          <TextField title='Pekerjaan Suami' value='' boxed />
          <TextField title='Umur Suami' value='' boxed />
          <TextField
            title='Nama Penanggung Jawab'
            value={result?.cp_name}
            boxed
          />
          <TextField title='Hubungan' value={result?.cp_relasi} boxed />
          <TextField title='Alamat' value='' boxed />
          <TextField title='Nomor Telepon / HP' value='' boxed />
          <TextField title='Nomor Kartu BPJS' value={result?.no_kapst} boxed />
        </div>
      </div>

      {/* Content */}
    </LayoutBorderNo>
  )
}
