import { Labor, Penlab } from '@/type'
import { formatDate } from '@/utils/formatDate'

export function PenunjangMedik({ data }: { data: Labor[] }) {
  const group: Record<string, Labor[]> = {}

  for (let i = 0; i < data.length; i++) {
    const curr = data[i]
    const tanggal = formatDate(curr.tanggal)

    if (!group[tanggal]) {
      group[tanggal] = []
    }
    group[tanggal].push(curr)
  }

  const list = Object.keys(group).map((k) => {
    return group[k]
  })

  console.log('list labor', list)

  if (list != null && list.length > 0) {
    return (
      <div className='border border-black'>
        {list.map((k, idx) => (
          <div key={idx}>
            <div className='p-1 bg-gray-300'>
              <p className='text-xs'>{formatDate(k[0].tanggal)}</p>
              <p className='text-xs'>Jam Mulai {formatDate(k[0].jaminput)}</p>
              <p className='text-xs'>
                Sampai Dengan {formatDate(k[0].jamselesai)}
              </p>
              <p className='text-xs'>Lama {k[0].lama}</p>
            </div>
            {k.map((item: Labor, index) => (
              <div key={`labor-${index}`}>
                <div className=' p-1 bg-gray-400'>
                  <h3 className='font-bold text-xs'>
                    {`${item?.nama_kelompok}`}
                  </h3>
                </div>
                <div>
                  <div className='flex items-start justify-between'>
                    <div className='w-full text-center border-r border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Deskripsi</h3>
                      </div>
                      {item.penlab
                        // .filter((i) => i.kategori != 'NORMAL')
                        .map((item: Penlab, index) => (
                          <p
                            key={`labor-penlab-deskripsi-${index}`}
                            className='text-start  px-2 text-xs'
                          >
                            {item.pemeriksaan_deskripsi}
                          </p>
                        ))}
                    </div>
                    <div className='w-full text-center border-r border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Normal</h3>
                      </div>
                      {item.penlab
                        // .filter((i) => i.kategori != 'NORMAL')
                        .map((item, index) => (
                          <p
                            key={`labor-normal-${index}`}
                            className='text-start  px-2 text-xs'
                          >
                            {item.normal} {item.satuan}
                          </p>
                        ))}
                    </div>
                    <div className='w-full text-center border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Hasil</h3>
                      </div>
                      {item.penlab
                        // .filter((i) => i.kategori != 'NORMAL')
                        .map((item, index) => (
                          <p
                            key={`labor-hasil-${index}`}
                            className='text-start  px-2 text-xs'
                          >
                            {item.hasil} {item.satuan}
                          </p>
                        ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    )
  } else {
    return (
      <p className='text-xs text-center font-medium'>
        Tidak ada pemeriksaan labor
      </p>
    )
  }
}
