import { useQuery } from "@tanstack/react-query";
import EmptyPlaceholder from "@/components/empty-placeholder";
import Error from "@/components/error";
import Loading from "@/components/loading";
import { getPemeriksaanLab } from "@/services/rekam-medis";
import { usePasienStore } from "@/store/pasien.store";
import { constants } from "@/utils/constants";
import { PenunjangMedik } from "./penunjang-medik";
import { LayoutBorderNo } from "@/components/layout_border_no";
import { InformasiPasien } from "@/components/informasi_pasien";
import { formatTanggalV2 } from "@/helper/date";

interface HasilPemeriksaanProps {
  isReport?: boolean;
  noreg?: string;
}

const HasilPemeriksaan = ({
  noreg = "",
  isReport = false,
}: HasilPemeriksaanProps) => {
  const { pasien } = usePasienStore((state) => state);

  const tglLahir = formatTanggalV2(
    pasien?.tgl_lahir || pasien?.tanggal_lahir || "",
  );

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.hasilLab, noreg],
    queryFn: () =>
      getPemeriksaanLab({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  });

  const res = data != null ? data.response : [];

  if (isLoading) return <Loading />;
  if (isError) return <Error />;
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message="Data tidak ditemukan." />;

  return (
    <LayoutBorderNo isReport={isReport}>
      <div className="p-4">
        <h1 className="text-center text-black font-semibold mb-1">
          HASIL PEMERIKSAAN LABORATORIUM
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={tglLahir}
            jk={pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}

        <div className="mt-4">
          <PenunjangMedik data={res} />
        </div>
      </div>
    </LayoutBorderNo>
  );
};

export default HasilPemeriksaan;
