import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getAsuhanKeperawatan } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportAsuhanKeperawatanProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

// Format target sesuai Flutter (ListConstants.toTarget)
function toTarget(kategori: string, angka: number): string {
  if (kategori == 'Meningkat') {
    if (angka == 1) return 'Meningkat'
    if (angka == 2) return 'Cukup Meningkat'
    if (angka == 3) return 'Sedang'
    if (angka == 4) return 'Cukup Menurun'
    if (angka == 5) return 'Menurun'
    return ''
  }
  if (kategori == 'Memburuk') {
    if (angka == 1) return 'Memburuk'
    if (angka == 2) return 'Cukup Memburuk'
    if (angka == 3) return 'Sedang'
    if (angka == 4) return 'Cukup Membaik'
    if (angka == 5) return 'Membaik'
    return ''
  }
  if (angka == 1) return 'Menurun'
  if (angka == 2) return 'Cukup Menurun'
  if (angka == 3) return 'Sedang'
  if (angka == 4) return 'Cukup Meningkat'
  if (angka == 5) return 'Meningkat'
  return ''
}

export function ReportAsuhanKeperawatan({
  isReport = false,
  no = 'RM.',
  noreg = '',
}: ReportAsuhanKeperawatanProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asuhanKeperawatan, noreg],
    queryFn: () => getAsuhanKeperawatan(noreg),
    enabled: noreg != '',
  })

  const list = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          RENCANA ASUHAN KEPERAWATAN
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {list.length === 0 ? (
          <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
        ) : (
          <div className='mb-2'>
            {list.map((item, i) => (
              <div key={item.no_daskep ?? i} className='mb-4'>
                <p className='text-[9px]'>
                  Diagnosa Keperawatan&nbsp;&nbsp;&nbsp;&nbsp;:{' '}
                  <span className='font-semibold'>
                    {item.diagnosa?.judul?.toUpperCase()} ({item.diagnosa?.kode}
                    )
                  </span>
                </p>
                <p className='text-[9px]'>
                  Defenisi&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                  : {item.diagnosa?.defenisi}
                </p>

                {/* Header */}
                <div className='flex mt-2'>
                  <SimpleColumn
                    head
                    name='Diagnosa Keperawatan (SDKI)'
                    className='p-1 flex-[1.1]'
                    className2='text-[9px]'
                  />
                  <SimpleColumn
                    head
                    name='TUJUAN (SLKI)'
                    className='p-1 flex-1'
                    className2='text-[9px]'
                  />
                  <SimpleColumn
                    head
                    name='INTERVENSI (SIKI)'
                    className='p-1 flex-1'
                    className2='text-[9px]'
                  />
                  <SimpleColumn
                    head
                    name='Paraf/Nama'
                    isLast
                    className='p-1 flex-1'
                    className2='text-[9px]'
                  />
                </div>

                {/* Body */}
                <div className='flex'>
                  <SimpleColumn
                    isChild={
                      <p className='text-[9px]'>{item.diagnosa?.judul}</p>
                    }
                    className='p-1 flex-[1.1]'
                  />
                  <SimpleColumn
                    isChild={
                      <div className='text-left'>
                        <p className='text-[9px] font-bold'>KRITERIA HASIL</p>
                        <p className='text-[9px] font-bold'>
                          Setelah di berikan asuhan keperawatan diharapkan :
                        </p>
                        {item.deskripsi_slki?.map((val, idx) => (
                          <p key={idx} className='text-[9px]'>
                            ◉ {val.waktu} /Jam , {val.nama_sllki}{' '}
                            {toTarget(val.kategori, val.target)}
                          </p>
                        ))}
                      </div>
                    }
                    className='p-1 flex-1'
                  />
                  <SimpleColumn
                    isChild={
                      <div className='text-left'>
                        {item.deskripsi_siki?.map((val, idx) => (
                          <p key={idx} className='text-[9px]'>
                            ◉ {val.nama_siki}
                          </p>
                        ))}
                      </div>
                    }
                    className='p-1 flex-1'
                  />
                  <SimpleColumn
                    isLast
                    isChild={
                      <div className='flex flex-col items-center gap-1'>
                        <QRCode
                          value={item.perawat?.nama ?? '-'}
                          className='h-[40px] w-[40px]'
                        />
                        <p className='text-[9px]'>{item.perawat?.nama}</p>
                      </div>
                    }
                    className='p-1 flex-1'
                  />
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
