const fmtDate = (v?: string) => {
  if (v == null || v == '') return ''
  const m = v.match(/^\d{4}-\d{2}-\d{2}/)
  return m ? m[0] : v
}

const MONTHS_ID = [
  'Januari',
  'Februari',
  'Maret',
  'April',
  'Mei',
  'Juni',
  'Juli',
  'Agustus',
  'September',
  'Oktober',
  'November',
  'Desember',
]

// Format tanggal seperti PDF: dd-MMMM-yyyy (31-Juli-2026)
const formatTglPDF = (v?: string) => {
  if (v == null || v == '') return ''
  const m = v.match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (!m) return v
  const month = MONTHS_ID[parseInt(m[2], 10) - 1]
  return `${parseInt(m[3], 10)}-${month}-${m[1]}`
}

// Lengkapi jam agar memuat detik seperti PDF (13:00 -> 13:00:00)
const timeFull = (v?: string) => {
  if (v == null || v == '') return ''
  return /^\d{1,2}:\d{2}$/.test(v) ? `${v}:00` : v
}

// ===== barcode Code39 (sesuai PDF: barbecue Code39 + checksum mod-43) =====
const CODE39_ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%'

function code39Check(value: string): string {
  let sum = 0
  for (const ch of value) {
    const idx = CODE39_ALPHABET.indexOf(ch)
    if (idx === -1) return ''
    sum += idx
  }
  return CODE39_ALPHABET[sum % 43]
}

