function checklistRows(value: string | undefined, items: ChecklistItem[]) {
  const lines = (value ?? '')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean)
  const rows: { label: string; checked: boolean }[] = []
  const used = new Set<number>()
  items.forEach((it) => {
    const m = norm(it.match ?? it.label)
    const idx = lines.findIndex((l, i) => {
      const n = norm(l)
      return (n.includes(m) || m.includes(n)) && !used.has(i)
    })
    if (idx >= 0) {
      used.add(idx)
      let label = it.label
      const n = norm(lines[idx])
      const at = n.indexOf(m)
      const extra = at >= 0 ? n.slice(at + m.length).trim() : ''
      if (extra) label = `${it.label} ${extra}`
      rows.push({ label, checked: true })
    } else {
      rows.push({ label: it.label, checked: false })
    }
  })
  const lain = lines.filter((_, i) => !used.has(i))
  return { rows, lain }
}

function Checklist({
  value,
  items,
}: {
  value?: string
  items: ChecklistItem[]
}) {
  const { rows, lain } = checklistRows(value, items)
  return (
    <div className='p-1' style={{ minHeight: 120 }}>
      {rows.map((r, i) => (
        <div key={i} className='flex gap-1 mb-0.5'>
          <span
            className={cn(
              'w-[9px] h-[9px] border border-black shrink-0 mt-[1px]',
              r.checked && 'bg-black'
            )}
          />
          <span className='text-xs leading-tight'>{r.label}</span>
        </div>
      ))}
      {lain.map((l, i) => (
        <div key={`l${i}`} className='flex gap-1 mb-0.5'>
          <span className='w-[9px] h-[9px] border border-black shrink-0 mt-[1px] bg-black' />
          <span className='text-xs leading-tight whitespace-pre-wrap'>{l}</span>
        </div>
      ))}
    </div>
  )
}

