import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { getPaps } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

interface ReportPernyataanPulangProps {
  isReport?: boolean
  noreg?: string
  no?: string
  no_rm?: string
}

export function ReportPernyataanPulang({
  isReport = false,
  no = '',
  noreg = '',
  no_rm = '',
}: ReportPernyataanPulangProps) {
  const { pasien } = usePasienStore((state) => state)

  const noRm = no_rm || pasien?.no_rm || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pernyataanPulang, noreg],
    queryFn: () => getPaps(noreg, noRm),
    enabled: noreg != '' && noRm != '',
  })

  const result = data != null ? data.response : null
  const dpaps = result?.dpaps

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (dpaps == null || dpaps.no_rm == '')
    return <EmptyPlaceholder message='Data tidak ditemukan' />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PERNYATAAN <br />
          PULANG ATAS PERMINTAAN SENDIRI
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}
        {/* Informasi Pasien */}

        <div className='p-2 border border-black space-y-2'>
          <p className='text-xs text-black'>
            Saya yang bertanda tangan di bawah ini:
          </p>
          <div className='ml-4 space-y-2.5'>
            <TextField title='Nama' value={dpaps?.nama} />
            <TextField title='Umur/Tanggal Lahir' value={dpaps?.umur} />
            <TextField title='Jenis Kelamin' value={dpaps?.jenis_kelamin} />
            <TextField title='Alamat' value={dpaps?.alamat} />
            <TextField title='Bukti diri / KTP' value={dpaps?.ktp} />
          </div>
          <p className='text-xs text-black'>
            Menyatakan dengan sesungguhnya bahwa saya telah mendapatkan
            penjelasan dari dokter dan mengerti mengenai kemungkinan-kemungkinan
            bahaya serta risiko yang akan timbul apabila menghentikan rawat inap
            (pulang paksa) terhadap pasien yang belum sembuh dari penyakitnya.
          </p>
          <p className='text-sm text-black font-medium'>
            MENGHENTIKAN RAWAT INAP (PULANG PAKSA)
          </p>
          <p className='text-xs text-black'>Terhadap {dpaps?.terhadap}</p>
          <div className='ml-4 space-y-2.5'>
            <TextField title='Nama' value={dpaps?.nama} />
            <TextField title='Tanggal Lahir' value={dpaps?.umur} />
            <TextField title='Jenis Kelamin' value={dpaps?.jenis_kelamin} />
            <TextField title='Alamat' value={dpaps?.alamat} />
            <TextField title='Bukti diri / KTP' value={dpaps?.ktp} />
            <TextField title='Dirawat di' value={dpaps?.dirawat} />
            <TextField title='No. RM' value={dpaps?.no_rm} />
            <TextField title='Alasan PAPS' value={dpaps?.alasan_paps} />
          </div>

          <p className='text-xs text-black'>
            Demikian surat pernyataan ini saya buat dengan kesadaran, tanpa
            paksaan serta menerima semua risiko dan tidak akan menuntut kepada
            pihak siapapun / pihak manapun.
          </p>

          {/*  QR */}
          {dpaps != null && (
            <>
              <div className='flex items-center justify-center gap-[100px] p-2 mb-4'>
                <div className='w-[150px] flex flex-col items-center gap-1'>
                  <p className='text-xs text-right'>Dokter / Pelaksana</p>
                  <QRCode
                    value={`${dpaps?.dokter_merawat ?? ''} - ${dpaps?.no_rm ?? ''}`}
                    className='h-[50px] w-[50px]'
                  />
                  <p className='text-xs text-center'>
                    ( {dpaps?.dokter_merawat ?? ''} )
                  </p>
                </div>

                <div className='w-[150px] flex flex-col items-center gap-1'>
                  <p className='text-xs text-center'>
                    Yang membuat
                    <br /> Pernyataan
                  </p>
                  <QRCode
                    value={`${dpaps?.pernyataan ?? ''} - ${dpaps?.no_rm ?? ''}`}
                    className='h-[50px] w-[50px]'
                  />
                  <p className='text-xs text-center'>
                    ( {dpaps?.pernyataan ?? ''} )
                  </p>
                </div>
              </div>{' '}
              <div className='flex items-center justify-center gap-[100px] p-2 mb-4'>
                <div className='w-[150px] flex flex-col items-center gap-1'>
                  <p className='text-xs text-right'>Saksi 1</p>
                  <QRCode
                    value={`${dpaps?.saksi1 ?? ''} - ${dpaps?.no_rm ?? ''}`}
                    className='h-[50px] w-[50px]'
                  />
                  <p className='text-xs text-center'>
                    ( {dpaps?.saksi1 ?? ''} )
                  </p>
                </div>

                <div className='w-[150px] flex flex-col items-center gap-1'>
                  <p className='text-xs text-right'>Saksi 2</p>
                  <QRCode
                    value={`${dpaps?.saksi2 ?? ''} - ${dpaps?.no_rm ?? ''}`}
                    className='h-[50px] w-[50px]'
                  />
                  <p className='text-xs text-center'>
                    ( {dpaps?.saksi2 ?? ''} )
                  </p>
                </div>
              </div>
            </>
          )}
          {/*  QR */}
        </div>
      </div>

      {/* Content */}
    </LayoutBorderNo>
  )
}
