import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { DoubleCheck } from '@/models/double-check'
import { getDoubleCheck } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportDoubleCheckProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportDoubleCheck({
  isReport = false,
  no = '',
  noreg = '',
}: ReportDoubleCheckProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.doubleCheck, noreg],
    queryFn: () => getDoubleCheck(noreg),
    enabled: noreg != '',
  })

  const list = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const aspects: {
    title: string
    pemberi: (record: DoubleCheck) => boolean
    verify: (record: DoubleCheck) => boolean
  }[] = [
    {
      title: 'PASIEN',
      pemberi: (r) => r.pasien_pemberi,
      verify: (r) => r.pasien_verify,
    },
    {
      title: 'OBAT',
      pemberi: (r) => r.obat_pemberi,
      verify: (r) => r.obat_verify,
    },
    {
      title: 'DOSIS',
      pemberi: (r) => r.dosis_pemberi,
      verify: (r) => r.dosis_verify,
    },
    {
      title: 'CARA',
      pemberi: (r) => r.cara_pemberi,
      verify: (r) => r.cara_verify,
    },
    {
      title: 'WAKTU',
      pemberi: (r) => r.waktu_pemberi,
      verify: (r) => r.waktu_verify,
    },
    {
      title: 'INFORMASI',
      pemberi: (r) => r.informasi_pemberi,
      verify: (r) => r.informasi_verify,
    },
    {
      title: 'DOKUMENTASI',
      pemberi: (r) => r.dokumentasi_pemberi,
      verify: (r) => r.dokumentasi_verify,
    },
  ]

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR DOUBLE CHECK HIGH ALERT MEDICATIONS
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {list.length === 0 ? (
          <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
        ) : (
          <div className='mb-2'>
            <div className='flex'>
              <SimpleColumn
                head
                name='NO'
                className='w-[30px] p-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='TANGGAL'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='NAMA OBAT'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              {aspects.map((a, i) => (
                <SimpleColumn
                  key={i}
                  head
                  name={`BENAR ${a.title}`}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              ))}
              <SimpleColumn
                head
                name='KETERANGAN'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='PERAWAT PEMBERI'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='PERAWAT VERIFIKASI'
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            {list.map((record, i) => (
              <div key={record.id_double_check ?? i} className='flex'>
                <SimpleColumn
                  name={`${i + 1}`}
                  className='w-[30px] p-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={record.insert_dttm}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={record.nama_obat}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                {aspects.map((a, ai) => (
                  <SimpleColumn
                    key={ai}
                    isChild={
                      <div className='text-[9px] leading-tight'>
                        <span>P: {a.pemberi(record) ? '✓' : '✗'}</span>
                        <br />
                        <span>V: {a.verify(record) ? '✓' : '✗'}</span>
                      </div>
                    }
                    className='p-1 flex-1'
                  />
                ))}
                <SimpleColumn
                  name={record.keterangan}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={record.perawat_pemberi || record.user?.nama}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={record.verify_nama}
                  isLast
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
