function formatTanggalJam(dateString: string): string {
  const date = new Date(dateString)

  const tahun = date.getFullYear()
  const bulan = (date.getMonth() + 1).toString().padStart(2, '0')
  const hari = date.getDate().toString().padStart(2, '0')

  const jam = date.getHours().toString().padStart(2, '0')
  const menit = date.getMinutes().toString().padStart(2, '0')
  const detik = date.getSeconds().toString().padStart(2, '0')

  return `Tanggal : ${tahun}-${bulan}-${hari}, Jam : ${jam}:${menit}:${detik} WIB`
}

function formatJam(dateString: string): string {
  const date = new Date(dateString)

  const jam = date.getHours().toString().padStart(2, '0')
  const menit = date.getMinutes().toString().padStart(2, '0')
  const detik = date.getSeconds().toString().padStart(2, '0')

  return `Jam : ${jam}:${menit}:${detik}`
}

