import type {  Diagnosa, Labor, Radiologi, Response } from '@/type'

import { post  } from './api-2'



const getAsesmenRajal = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<RajalMedis>> => {
  const response = await post(`/v1/asesmen-medis-rajal`, { noreg: noreg })
  return response.data
}

export { getAsesmenRajal }





