import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { getPersetujuanHiv } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

interface ReportPersetujuanHivProps {
  isReport?: boolean
  noreg?: string
  no?: string
  no_rm?: string
}

export function ReportPersetujuanHiv({
  isReport = false,
  no = '',
  // noreg = '',
  no_rm = '',
}: ReportPersetujuanHivProps) {
  const { pasien } = usePasienStore((state) => state)

  const noRm = no_rm || pasien?.no_rm || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.persetujuanHiv, noRm],
    queryFn: () => getPersetujuanHiv(noRm),
    enabled: noRm != '',
  })

  const result = data != null ? data.response : null
  const pasienData = result?.pasien
  const tandaTangan = result?.bertanda_tangan

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PERSETUJUAN PEMERIKSAAN HIV DAN HEPATITIS B SKRENING (UJI SARING)
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        <div className='p-2 border border-black space-y-2.5 mb-4'>
          <p className='text-xs text-black'>
            Saya yang bertanda tangan di bawah ini menyetujui dilakukan
            pemeriksaan HIV terhadap pasien dan bersedia menerima informasi
            hasil pemeriksaan sesuai ketentuan yang berlaku.
          </p>
          <TextField title='Nama' value={tandaTangan?.nama} />
          <TextField title='Alamat' value={tandaTangan?.alamat} />
        </div>

        <div className='p-2 border border-black space-y-2.5 mb-4'>
          <p className='text-xs text-black font-medium'>Data Pasien</p>
          <TextField title='Nama' value={pasienData?.nama} />
          <TextField title='Tanggal Lahir' value={pasienData?.tgl_lahir} />
          <TextField title='Jenis Kelamin' value={pasienData?.jenis_kelamin} />
          <TextField title='Alamat' value={pasienData?.alamat} />
          <TextField title='No. RM' value={pasienData?.no_rm} />
          <TextField title='No. Register' value={pasienData?.noreg} />
          <TextField title='Nama Perawat' value={result?.nama_perawat} />
          <TextField
            title='Nama Petugas Labor'
            value={result?.nama_petugas_labor}
          />
          <TextField title='Tanggal' value={result?.tanggal} />
        </div>

        <div className='p-2 border border-black mb-4'>
          <p className='text-xs text-black'>
            Dengan ini menyatakan <span className='font-bold'>SETUJU</span>{' '}
            untuk Test HIV dan Hepatitis B sebagai uji saring (Skrening).
            Bersedia bertanggung jawab untuk dilakukan pemeriksaan di atas.
          </p>
        </div>

        {/* Tanda Tangan */}
        <div className='flex items-start justify-around p-2'>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>Perawat/Bidan</p>
            <QRCode
              value={result?.nama_perawat ?? '-'}
              className='h-[80px] w-[80px]'
            />
            <p>( {result?.nama_perawat ?? ''} )</p>
          </div>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>Petugas Labor</p>
            <QRCode
              value={result?.nama_petugas_labor ?? '-'}
              className='h-[80px] w-[80px]'
            />
            <p>( {result?.nama_petugas_labor ?? ''} )</p>
          </div>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>Yang Membuat Pernyataan</p>
            <QRCode
              value={tandaTangan?.nama ?? '-'}
              className='h-[80px] w-[80px]'
            />
            <p>( {tandaTangan?.nama ?? ''} )</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
