import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { cn } from '@/lib/utils'
import { getTindakanTransfusiDarah } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportTindakanTransfusiDarahProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

// Baris checklist sesuai form Flutter (persetujuan tindakan transfusi darah)
const CHECKLIST: {
  key:
    | 'value1'
    | 'value2'
    | 'value3'
    | 'value4'
    | 'value5'
    | 'value6'
    | 'value7'
    | 'value8'
  title: string
}[] = [
  { key: 'value1', title: 'Tujuan Tranfusi Darah' },
  { key: 'value2', title: 'Manfaat Tranfusi Darah' },
  { key: 'value3', title: 'Perkiraan jumlah yang diberikan' },
  { key: 'value4', title: 'Resiko dan komplikasi yang mungkin terjadi' },
  {
    key: 'value5',
    title: 'Alternatif lain yang bisa dilakukan tanpa tranfusi darah',
  },
  { key: 'value6', title: 'Perkiraan biaya' },
  {
    key: 'value7',
    title:
      'Tindakan tambahan kemungkinan diperlukan jika dokter menemukan sesuatu yang tak terduga',
  },
  {
    key: 'value8',
    title:
      'Tindakan ini kemungkinan tidak memberikan hasil yang sesuai harapan walaupun sudah dilakukan sesuai standart prosedur yang berlaku',
  },
]

function CekItem({ title, value }: { title: string; value?: boolean }) {
  return (
    <div className='flex border border-black'>
      <div className='flex-1 p-1 text-[9px] flex items-center'>{title}</div>
      <div className='w-[40px] shrink-0 border-l border-black flex items-center justify-center text-[9px]'>
        {value ? '☑' : '☐'}
      </div>
    </div>
  )
}

function TandaTanganBox({ title, nama }: { title: string; nama?: string }) {
  return (
    <div className='flex-1 flex flex-col items-center gap-1 p-3 text-center text-xs'>
      <p className='font-semibold'>{title}</p>
      <QRCode value={nama ?? '-'} className='h-[70px] w-[70px]' />
      <p>( {nama ?? ''} )</p>
    </div>
  )
}

export function ReportTindakanTransfusiDarah({
  isReport = false,
  no = '',
  noreg = '',
}: ReportTindakanTransfusiDarahProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.tindakanTransfusiDarah, noreg],
    queryFn: () => getTindakanTransfusiDarah(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result == null || result.noreg == '')
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
      </LayoutBorderNo>
    )

  const isSetuju = result.menyatakan == 'SETUJU'

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PERSETUJUAN TINDAKAN / PENOLAKAN PEMBERIAN TRANFUSI DARAH
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        <div className='mb-3'>
          {CHECKLIST.map((item) => (
            <CekItem
              key={item.key}
              title={item.title}
              value={result[item.key]}
            />
          ))}
        </div>

        <p className='text-xs text-black mb-3 px-2'>
          Saya sudah mendapat kesempatan untuk bertanya dan saya sudah mengerti
          dan puas dengan penjelasan yang diberikan sehubungan dengan
          pertanyaan-pertanyaan saya, disamping itu jika terjadi kecelakaan
          seperti darah terinfeksi HIV dan penyakit lainnya, saya memberikan
          izin untuk mengambil darah pasien untuk tes HIV dan penyakit lainnya
          yang penularannya melalui darah.
        </p>

        <p className='text-xs text-black mb-2 px-2'>
          Dengan ini saya menyatakan :
        </p>

        <div className='flex gap-2 px-2 mb-2'>
          <span
            className={cn(
              'border border-black px-6 py-1 text-xs font-bold',
              isSetuju ? 'bg-green-200' : 'bg-gray-100 text-gray-500'
            )}
          >
            SETUJU
          </span>
          <span
            className={cn(
              'border border-black px-6 py-1 text-xs font-bold',
              !isSetuju ? 'bg-green-200' : 'bg-gray-100 text-gray-500'
            )}
          >
            MENOLAK
          </span>
        </div>

        <p className='text-xs text-black mb-4 px-2'>
          untuk dilakukan pemberian tranfusi darah yang sudah dijelaskan diatas.
        </p>

        {/* Verifikasi tanda tangan 2x2 */}
        <div className='border border-black'>
          <div className='flex border-b border-black'>
            <div className='flex-1'>
              <p className='text-center text-[9px] font-bold bg-gray-100 p-1'>
                VERIFIKASI TANDA TANGAN DOKTER
              </p>
              <TandaTanganBox title='Dokter' nama={result.nama_dokter} />
            </div>
            <div className='flex-1 border-l border-black'>
              <p className='text-center text-[9px] font-bold bg-gray-100 p-1'>
                VERIFIKASI TANDA TANGAN PEMBUAT PERNYATAAN
              </p>
              <TandaTanganBox
                title='Pembuat Pernyataan'
                nama={result.nama_pernyataan}
              />
            </div>
          </div>
          <div className='flex'>
            <div className='flex-1'>
              <p className='text-center text-[9px] font-bold bg-gray-100 p-1'>
                VERIFIKASI TANDA TANGAN SAKSI 1
              </p>
              <TandaTanganBox title='Saksi 1' nama={result.nama_saksi1} />
            </div>
            <div className='flex-1 border-l border-black'>
              <p className='text-center text-[9px] font-bold bg-gray-100 p-1'>
                VERIFIKASI TANDA TANGAN SAKSI 2
              </p>
              <TandaTanganBox title='Saksi 2' nama={result.nama_saksi2} />
            </div>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
