import { DaftarObat } from '@/models/pemberian_obat'
import type { Response } from '@/type'
import { post } from './api-2'
import { RekonsiliasiObatPulang } from '@/models/rekonsiliasi-obat-pulang'
import { RekonsiliasiObatMasuk } from '@/models/rekonsiliasi-obat-pulang-masuk'
