import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getAnalisaData } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportAnalisaDataProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportAnalisaData({
  isReport = false,
  no = '',
  noreg = '',
}: ReportAnalisaDataProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.analisaData, noreg],
    queryFn: () => getAnalisaData(noreg),
    enabled: noreg != '',
  })

  const list = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          ANALISA DATA
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {list.length === 0 ? (
          <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
        ) : (
          <div className='mb-2'>
            <div className='flex'>
              <SimpleColumn
                head
                name='NO.'
                className='w-[30px] p-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Tgl/Jam Ditemukan'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='DATA'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='PROBLEM'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Tgl/Jam Teratasi'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='NAMA PERAWAT'
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            {list.map((item, i) => (
              <div key={item.id ?? i} className='flex'>
                <SimpleColumn
                  name={`${i + 1}`}
                  className='w-[30px] p-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={item.insert_dttm}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={item.data}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isChild={
                    <p className='text-[9px] text-left'>
                      {item.analisa_data
                        ?.map((a) => `${a.id_diagnosa}-${a.nama_diagnosa}`)
                        .join(', ')}
                    </p>
                  }
                  className='p-1 flex-1'
                />
                <SimpleColumn
                  name={`${item.tgl} ${item.jam}`}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isLast
                  isChild={
                    <div className='flex flex-col items-center gap-1'>
                      <QRCode
                        value={item.pegawai?.nama ?? '-'}
                        className='h-[40px] w-[40px]'
                      />
                      <p className='text-[9px]'>{item.pegawai?.nama}</p>
                    </div>
                  }
                  className='p-1 flex-1'
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
