export const TextField = ({
  title,
  value,
  isbool,
  boxed = false,
}: {
  title: string
  value?: string
  isbool?: boolean
  boxed?: boolean
}) => {
  // Mode boxed: tiap karakter dalam kotak ber-border sendiri
  if (boxed) {
    return (
      <div className='my-1'>
        <div className='flex items-start'>
          <div className='min-w-[250px]'>
            <p className={`text-xs ${isbool ? 'font-bold' : ''}`}>{title ?? ''}</p>
          </div>
          <div className='flex flex-wrap gap-[2px]'>
            {(value ?? '').split('').map((char, i) => (
              <span
                key={i}
                className='inline-flex h-5 w-5 items-center justify-center border border-black text-xs'
              >
                {char === ' ' ? '\u00A0' : char}
              </span>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className='my-1'>
      <div className='flex items-center'>
        <div className='min-w-[250px]'>
          <p className={`text-xs ${isbool ? 'font-bold' : ''}`}>{title ?? ''}</p>
        </div>
        <div>
          <p className={`text-xs ${isbool ? 'font-bold' : ''}`}>
            {value != '' ? `: ${value}` : ''}
          </p>
        </div>
      </div>
    </div>
  )
}
