import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import { images } from '@/assets/images/images'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import Text from '@/components/text'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { LaborTable } from '@/features/pasien-pulang/rekam-medis/components/labor-table'
import { RadiologiTable } from '@/features/pasien-pulang/rekam-medis/components/radiologi-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import { formatTanggal } from '@/helper/date'
import { getAsesmenRajal } from '@/services/medis-rajal'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import PhysicalExamReport from './PEMFISIK'

interface AsesmenRawatJalanProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function AsesmenRawatJalan({
  isReport = false,
  noreg,
}: AsesmenRawatJalanProps) {
  // store //
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenMedisRajal, noreg],
    queryFn: () => getAsesmenRajal({ noreg: noreg ?? '' }),
    // enabled: noreg,
  })

  const res = data != null ? data.response : null

  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null) return <Error />

  const dataMap = [
    { label: 'TD', value: res?.rajal.td ?? '-', unit: 'mmHg' },
    { label: 'Nadi', value: res?.rajal.nadi ?? '-', unit: 'x/mnt' },
    { label: 'RR', value: res?.rajal.pernafasan ?? '-', unit: 'x/mnt' },
    { label: 'Suhu', value: res?.rajal.suhu ?? '-', unit: '°C' },
    { label: 'SpO2', value: res?.rajal.spo2 ?? '-', unit: '%' },
    { label: 'BB', value: res?.rajal.bb ?? '-', unit: 'Kg' },
  ]

  const hasilPemeriksaan = {
    Kepala: res?.rajal.kepala ?? '-',
    Mata: res?.rajal.mata ?? '-',
    THT: res?.rajal.tht ?? '-',
    Mulut: res?.rajal.mulut ?? '-',
    Leher: res?.rajal.leher ?? '-',
    Dada: res?.rajal.dada ?? '-',
    Jantung: res?.rajal.jantung ?? '-',
    Paru: res?.rajal.paru ?? '-',
    Perut: res?.rajal.perut ?? '-',
    Hati: res?.rajal.hati ?? '-',
    Limpa: res?.rajal.limpa ?? '-',
    Ginjal: res?.rajal.ginjal ?? '-',
    Alat_Kelamin: res?.rajal.alat_kelamin ?? '-',
    Anggota_Gerak: res?.rajal.anggota_gerak ?? '-',
    Refleks: res?.rajal.refleks ?? '-',
    Kekuatan_Otot: res?.rajal.kekuatan_otot ?? '-',
    Kulit: res?.rajal.kulit ?? '-',
    Kel_Getah_Bening: res?.rajal.kelenjar_getah_bening ?? '-',
    RT_VT: res?.rajal.rt_vt ?? '-',
  }

  return (
    <>
      <LayoutBorderNo isReport={isReport}>
        {/* Content */}
        <div className='p-2 '>
          <h1 className='text-center text-black font-semibold mb-1'>
            ASESMEN AWAL MEDIS RAWAT JALAN (diisi oleh dokter)
          </h1>

          {/* Tanggal dan Jam */}
          <div className='flex items-center gap-4 border border-black my-2 p-2'>
            <p className='flex-1'>
              Tanggal {res?.rajal.tgl} / Jam: {res?.rajal.jam} WIB
            </p>
          </div>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien}
              noRM={pasien.no_rm}
              ruangan={res.rajal.ruangan} //{res.rajal.ruangan}
              tanggalLahir={formatTanggal(res.rajal.tgllahir)}
            />
          )}
          {/* Informasi Pasien */}
        </div>
        {/* Content */}

        <div className='border border-black my-2 p-2'>
          <p className='flex-1 font-semibold'>SUBJEKTIF</p>
          <Text
            kStyle='min-w-[250px]'
            k='Keluhan Utama'
            v={res?.rajal.asesmed_keluh_utama ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Sekarang'
            v={res?.rajal.asesmed_rwyt_skrg ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Dahulu'
            v={res?.rajal.asesmed_rwyt_dahulu ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Keluarga'
            v={res?.rajal.penyakit_keluarga ?? '-'}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <p className='flex-1 font-semibold'>OBJEKTIF</p>
          <p className='flex-1 font-semibold mb-3'>Tanda - Tanda Vital </p>

          <div className='w-full bg-white-4 rounded-md'>
            <div className='grid grid-cols-3 gap-y-2 gap-x-8 text-xs'>
              {dataMap.map((item, index) => (
                <div key={index} className='flex items-center gap-2'>
                  <span className='w-12 font-medium'>{item.label}</span>
                  <span>:</span>
                  <span className='font-semibold text-xs'>{item.value}</span>
                  <span className='text-gray-600 text-xs'>{item.unit}</span>
                </div>
              ))}
            </div>
          </div>

          <div className='mb-2 mt-2 font-medium'>
            Pemeriksaan Fisik <span className='ml-2'>:</span>
            <PhysicalExamReport
              data={hasilPemeriksaan}
              examDate={res?.rajal.tgl + ' ' + res?.rajal.jam}
            />
          </div>
        </div>

        <div className='flex items-center justify-center'>
          <img
            src={res?.rajal.image_lokalis}
            alt='anatomi tubuh'
            className='object-contain h-[300px]'
          />
          <img
            src={images.keterangan}
            alt='keterangan'
            className='object-contain h-[200px]'
          />
        </div>

        {/* Dokter Yang Memeriksa */}

        {/* Dokter Yang Memeriksa */}

        {/* Pemeriksaan Penunjang */}
        <div className='border border-black my-2 p-2'>
          <p className='flex-1 font-semibold'>PEMERIKSAAN PENUNJANG</p>
          <div>
            <TextTitle title='Laboratorium' />
            <LaborTable data={res != null ? res.labor : []} />
          </div>
          <div>
            <TextTitle title='Pemeriksaan Lain' />
            <RadiologiTable data={res != null ? res.radiologi : []} />
          </div>
        </div>
        {/* Pemeriksaan Penunjang */}

        {/* Asesmen */}
        <div className='border border-black my-2 p-2'>
          <div className='flex items-center justify-between'>
            <TextTitle title='Asesmen (Diagnosa Kerja)' />
          </div>
          <DiagnosaTable data={res != null ? res.diagnosa : []} />
        </div>
        {/* Asesmen */}

        {/* SECTION: PLANNING */}
        <div className='mb-6 text-xs'>
          <h3 className='font-bold border-b-2 border-gray-800 mb-3 pb-1'>
            PLANNING
          </h3>
          <div className='grid grid-cols-[180px_10px_1fr] gap-y-3 pl-2'>
            <span className='text-gray-600'>Kondisi Pulang</span>
            <span>:</span>
            <div className='flex items-center gap-2'>
              <div className='w-5 h-5 border border-black flex items-center justify-center font-bold'>
                {res.rajal.kondisi_pulang ? '✓' : ''}
              </div>
              <span>{res.rajal.kondisi_pulang || '-'}</span>
            </div>

            <span className='text-gray-600'>Cara Keluar</span>
            <span>:</span>
            <div className='flex items-center gap-2'>
              <div className='w-5 h-5 border border-black flex items-center justify-center font-bold'>
                {res.rajal.cara_keluar ? '✓' : ''}
              </div>
              <span>{res.rajal.cara_keluar || '-'}</span>
            </div>

            <span className='text-gray-600'>Instruksi Tindak Lanjut</span>
            <span>:</span>
            <div className='flex flex-col gap-1'>
              <div className='flex items-center gap-2'>
                <div className='w-5 h-5 border border-black flex items-center justify-center font-bold'>
                  {/* {res.rajal.instruksi ? '✓' : ''} */}
                </div>
                {/* <span className='font-bold'>{res.rajal.instu || '-'}</span> */}
              </div>
              {/* {(planning.klinik || planning.dokter) && (
                <div className='ml-7 p-2 bg-gray-50 border-l-2 border-gray-300'>
                  <p className='font-medium text-gray-800'>{planning.klinik}</p>
                  <p className='text-gray-600'>{planning.dokter}</p>
                </div>
              )} */}
            </div>
          </div>
        </div>

        <div className='border border-black my-2 p-2'>
          {res?.terapi.length == 0 && (
            <p className='flex-1 font-semibold'>Tidak ada terapi</p>
          )}

          {res?.terapi?.length > 0 && (
            <div className='mt-4'>
              <p className='font-semibold mb-2'>Terapi</p>

              {res.terapi.map((item, index) => (
                <div key={index} className='my-2'>
                  <div className='grid grid-cols-2 gap-2 text-sm'>
                    <p>
                      <span className='font-semibold'></span> {item.nama_obat}
                    </p>
                    <p>
                      <span className='font-semibold'></span> {item.jumlah}{' '}
                      {item.satuan}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {res?.rajal.kontrol_dokter != '' ||
          (res?.rajal.konsul_dokter != '' && (
            <div className='text-sm'>
              <h3 className='font-bold border-b-2 border-gray-800 mb-3 pb-1'>
                RENCANA PEMERIKSAAN PENUNJANG
              </h3>
              <div className='grid grid-cols-[180px_10px_1fr] gap-y-3 pl-2'>
                <span className='font-bold'>LABORATORIUM</span>
                <span>:</span>
                <span className={'font-medium'}>
                  {res?.rajal.rencana_laborat}
                </span>

                <span className='font-bold'>RADIOLOGI</span>
                <span>:</span>
                <span className={'font-medium'}>
                  {res?.rajal.rencana_radiologi}
                </span>
                <span className='font-bold'>LAINNYA</span>
                <span>:</span>
                <span className={'font-medium'}>
                  {res?.rajal.rencana_penmed_lain}
                </span>

                <span className='font-bold'>PROGNOSA</span>
                <span>:</span>
                <span className={'font-medium'}>
                  {res?.rajal.asesmed_prognosis}
                </span>
              </div>
            </div>
          ))}

        <div className='text-center'>
          <h3 className='text-xs p-2 font-medium'>
            Pasien dan Keluarga telah dijelaskan tentang Diagnosa , Kondisi,
            Rencana perawatan ,pemeriksaan, pengobatan dan prognosa pasien saat
            ini. <br />
            Pasien dan Keluarga sudah mengerti.
          </h3>
        </div>

        <div className='p-2 mb-1 m-2 flex flex-row flex-wrap justify-around items-start gap-10'>
          <div className='flex flex-col gap-12 items-center text-center text-xs'>
            {res != null && res?.rajal.namaperawat != '' && (
              <>
                <p className='text-sm'>Perawat</p>
                <QRCode
                  value={res?.rajal.namaperawat ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({res?.rajal.namaperawat ?? '-'})</p>
              </>
            )}
          </div>
          <div className='flex flex-col gap-12 items-center text-center text-xs'>
            {res != null && res?.rajal.namadokter != '' && (
              <>
                <p className='text-sm'>Pasien/Keluarga</p>
                <QRCode
                  value={res?.rajal.namadokter ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({res?.rajal.firstname ?? '-'})</p>
              </>
            )}
          </div>

          <div className='flex flex-col gap-12 items-center text-center text-xs'>
            {res != null && res?.rajal.namadokter != '' && (
              <>
                <p className='text-sm'>Dokter Yang Memeriksa</p>
                <QRCode
                  value={res?.rajal.namadokter ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({res?.rajal.namadokter ?? '-'})</p>
              </>
            )}
          </div>
        </div>
      </LayoutBorderNo>
    </>
  )
}
